package punch

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
)

// Wire format for every punch datagram (little-endian fixed header):
//
//	 0:4   magic "WTPN"
//	 4     protocol version (1)
//	 5     frame type (probe / pong / data)
//	 6:22  session id (16 random bytes)
//	22:30  sequence number (uint64)
//	30:    payload
//	last32 HMAC-SHA256 over all preceding bytes
//
// The per-session HMAC key is generated by the offerer and delivered inside
// the sealed fabric signaling envelope, so a NAT or on-path observer cannot
// forge or read punch traffic even though the datagrams themselves ride plain
// UDP.
const (
	magicBytes   = "WTPN"
	protoVersion = 1

	frameProbe uint8 = 1
	framePong  uint8 = 2
	frameData  uint8 = 3

	sessionIDLen = 16
	keyLen       = 32
	hmacLen      = sha256.Size

	headerLen = 4 + 1 + 1 + sessionIDLen + 8

	// MaxDatagram keeps every frame inside one unfragmented UDP datagram
	// that fits typical NAT and PPPoE MTU budgets.
	MaxDatagram = 1280
	MaxPayload  = MaxDatagram - headerLen - hmacLen
)

// ErrFrame marks a datagram that is not a valid punch frame for this key.
// The punch reader treats it as unrelated traffic and keeps waiting.
var ErrFrame = errors.New("punch: malformed frame")

type frame struct {
	FrameType uint8
	SessionID []byte
	Seq       uint64
	Payload   []byte
}

// seal frames and authenticates f with key, returning the ready datagram.
func (f frame) seal(key []byte) []byte {
	buf := make([]byte, 0, headerLen+len(f.Payload)+hmacLen)
	buf = append(buf, magicBytes...)
	buf = append(buf, protoVersion, f.FrameType)
	buf = append(buf, f.SessionID...)
	var seq [8]byte
	binary.LittleEndian.PutUint64(seq[:], f.Seq)
	buf = append(buf, seq[:]...)
	buf = append(buf, f.Payload...)
	mac := hmac.New(sha256.New, key)
	mac.Write(buf)
	return mac.Sum(buf)
}

// openFrame verifies and decodes a received datagram. It returns ErrFrame
// for anything that fails the magic, version, frame type, or HMAC check.
func openFrame(datagram []byte, key []byte) (frame, error) {
	if len(datagram) < headerLen+hmacLen {
		return frame{}, ErrFrame
	}
	if string(datagram[:4]) != magicBytes {
		return frame{}, ErrFrame
	}
	if datagram[4] != protoVersion {
		return frame{}, fmt.Errorf("%w: version %d", ErrFrame, datagram[4])
	}
	body := len(datagram) - hmacLen
	mac := hmac.New(sha256.New, key)
	mac.Write(datagram[:body])
	if !hmac.Equal(datagram[body:], mac.Sum(nil)) {
		return frame{}, fmt.Errorf("%w: bad hmac", ErrFrame)
	}
	switch datagram[5] {
	case frameProbe, framePong, frameData:
	default:
		return frame{}, fmt.Errorf("%w: type %d", ErrFrame, datagram[5])
	}
	return frame{
		FrameType: datagram[5],
		SessionID: append([]byte(nil), datagram[6:6+sessionIDLen]...),
		Seq:       binary.LittleEndian.Uint64(datagram[6+sessionIDLen : headerLen]),
		Payload:   append([]byte(nil), datagram[headerLen:body]...),
	}, nil
}
